/**
 * Generates the frozen demonstration cases and writes them to content/case/.
 *
 *   npm run case:generate
 *
 * Two sections are produced:
 *
 *   primary   — an untreated tumour section, the case the workflow runs on.
 *   reference — a matched section with far more vasculature and much less
 *               hypoxia, offered as the optional §6.8 comparison.
 *
 * The reference exists to exercise the comparability machinery honestly. It is
 * generated by the same model, on the same platform, with the same panel, so it
 * *is* comparable — and the lab's comparability check says so for a stated
 * reason rather than by assumption. A third section on a different panel is
 * generated too, precisely so that the refusal path has something to refuse.
 */

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..', '..');
const dist = join(root, 'engine', 'dist');

const { compileNetwork } = await import(join(dist, 'propagate', 'network.js'));
const { generateTissue, DEMONSTRATION_SPEC } = await import(join(dist, 'data', 'tissue.js'));
const format = await import(join(dist, 'data', 'caseFormat.js'));

const network = compileNetwork();
const outputDir = join(root, 'content', 'case');
mkdirSync(outputDir, { recursive: true });

function freeze(tissue, options) {
  const observationCount = tissue.dataset.observations.length;
  const nodeCount = network.nodes.length;

  // The exogenous drive is stored per node that actually has one. In this model
  // that is HIF1A alone, so the dense form would be 98% zeros.
  const exogenous = [];
  for (let node = 0; node < nodeCount; node += 1) {
    let anyNonZero = false;
    const column = new Float64Array(observationCount);
    for (let i = 0; i < observationCount; i += 1) {
      const value = tissue.exogenous.values[i * nodeCount + node];
      column[i] = value;
      if (value !== 0) anyNonZero = true;
    }
    if (anyNonZero) exogenous.push({ nodeIndex: node, values: format.encodeFloat32(column) });
  }

  return {
    format: 'spatial-case-v1',
    caseId: options.caseId,
    title: options.title,
    description: options.description,
    simulationNotice:
      'SIMULATED TISSUE. This section was generated by the spatial-omics-engine tissue model, not measured. ' +
      'Cells were placed by Poisson-disc rejection into a tumour core, periphery, invasive margin and stroma; cell-type identity ' +
      'sets which network nodes each cell can express; hypoxia enters as a sustained drive on HIF1A from vessel distance; and a ' +
      'curated 64-node intracellular network coupled by diffusible ligands was relaxed to a steady state. Counts are ' +
      'negative-binomial draws from that state. Every result computed on this case is a statement about that model and about ' +
      'nothing else.',
    generatedAt: new Date().toISOString(),
    engineVersion: '1.0.0',
    spec: tissue.spec,

    metadata: tissue.dataset.metadata,
    observations: tissue.dataset.observations,
    features: tissue.dataset.features,
    matrix: format.encodeInt32(tissue.dataset.matrix),
    checksum: tissue.dataset.checksum,
    revision: tissue.dataset.revision,
    ingestion: tissue.dataset.ingestion,

    truth: format.encodeFloat32(tissue.truth.activity),
    capacity: format.encodeFloat32(tissue.capacity.values),
    exogenous,
    ligandReference: format.encodeFloat64(tissue.context.ligandReference),
    nodeCount,
    nodeSymbols: network.nodes.map((n) => n.symbol),

    cellTypes: tissue.cellTypes,
    regions: tissue.regions,
    vesselDistance: format.encodeFloat32(tissue.vesselDistance),

    role: options.role,
    comparableWith: options.comparableWith,
  };
}

const cases = [
  {
    spec: DEMONSTRATION_SPEC,
    caseId: 'sim-tme-primary',
    role: 'primary',
    title: 'Simulated tumour microenvironment — untreated',
    description:
      'A 2,400-cell simulated section with an irregular tumour mass, an invasive margin rich in immune cells, surrounding ' +
      'stroma and seven vessels. The tumour core sits furthest from any vessel and carries the strongest hypoxic signalling. ' +
      'Tumour, fibroblast, macrophage, T-cell and endothelial compartments each express a different part of the panel.',
    comparableWith: ['sim-tme-vascular-reference'],
  },
  {
    spec: {
      ...DEMONSTRATION_SPEC,
      sampleId: 'SIM-TME-REF',
      seed: 20260822,
      vesselCount: 20,
      intratumoralVesselFraction: 0.55,
      tumourFraction: 0.3,
      immuneInfiltration: 0.6,
      condition: 'Tumour, well-vascularised reference',
    },
    caseId: 'sim-tme-vascular-reference',
    role: 'reference',
    title: 'Simulated tumour microenvironment — well-vascularised reference',
    description:
      'The same tissue model with twenty-two vessels instead of seven, so almost no cell is far enough from perfusion to ' +
      'become hypoxic. Offered as the §6.8 reference comparison: same organism, assay, resolution, panel and platform, ' +
      'differing in the one thing the comparison is about.',
    comparableWith: ['sim-tme-primary'],
  },
];

for (const entry of cases) {
  process.stdout.write(`generating ${entry.caseId}…\n`);
  const started = Date.now();
  const tissue = generateTissue(entry.spec, network);
  const frozen = freeze(tissue, entry);
  const path = join(outputDir, `${entry.caseId}.json`);
  writeFileSync(path, JSON.stringify(frozen));
  const counts = {};
  for (const type of tissue.cellTypes) counts[type] = (counts[type] ?? 0) + 1;
  process.stdout.write(
    `  ${tissue.dataset.observations.length} cells, ${tissue.dataset.features.length} features, ` +
      `${(JSON.stringify(frozen).length / 1024 / 1024).toFixed(2)} MB, ${((Date.now() - started) / 1000).toFixed(1)}s\n` +
      `  composition: ${Object.entries(counts).map(([k, v]) => `${k} ${v}`).join(', ')}\n` +
      `  checksum ${tissue.dataset.checksum.slice(0, 16)}\n`,
  );
}

process.stdout.write(`wrote ${cases.length} case(s) to ${outputDir}\n`);
